const item = $input.first().json;
const allowedId = $env.TELEGRAM_ALLOWED_USER_ID || 'TU_CHAT_ID';

let userId = null;
let chatId = null;
let text = '';
let isCallback = false;
let callbackData = '';
let callbackQueryId = null;

if (item.callback_query) {
  isCallback = true;
  userId = item.callback_query.from.id;
  chatId = item.callback_query.message.chat.id;
  callbackData = item.callback_query.data;
  callbackQueryId = item.callback_query.id;
} else if (item.message) {
  userId = item.message.from.id;
  chatId = item.message.chat.id;
  text = item.message.text || '';
}

const isAuthorized = String(userId) === String(allowedId);

return [{
  json: {
    isAuthorized,
    userId,
    chatId,
    text,
    isCallback,
    callbackData,
    callbackQueryId
  }
}];

const item = $input.first().json;
let cmd = '';
let action = 'menu';

if (item.isCallback) {
  action = item.callbackData;
  if (action === 'btn_status') {
    cmd = '/var/packages/ContainerManager/target/usr/bin/docker ps -a --filter name=kali_linux --format "Estado: {{.Status}}"';
  } else if (action === 'btn_ip') {
    cmd = '/var/packages/ContainerManager/target/usr/bin/docker exec kali_linux ip -brief addr show';
  } else if (action === 'btn_scan_arp') {
    cmd = '/var/packages/ContainerManager/target/usr/bin/docker exec kali_linux arp-scan --localnet';
  }
} else if (item.text.startsWith('/exec ')) {
  action = 'exec';
  const cleanCmd = item.text.replace('/exec ', '').trim();
  cmd = `/var/packages/ContainerManager/target/usr/bin/docker exec kali_linux ${cleanCmd}`;
} else if (item.text.startsWith('/status')) {
  action = 'status';
  cmd = '/var/packages/ContainerManager/target/usr/bin/docker ps -a --filter name=kali_linux --format "Estado: {{.Status}}"';
}

return [{
  json: {
    ...item,
    action,
    cmd
  }
}];
